import { GEO } from './terrassa-geodata.js';

// js/city-config.js
// Terrassa's spatial configuration & street database at true 1:1 scale, derived from the real geography in
// js/terrassa-geodata.js (generated by tools/build-geodata.mjs from OpenStreetMap; fidelity notes in HOW_TO_IMPROVE.md).
//
// World frame: 1 unit = 1 m, x = east along the Eixample's street grid, z = grid south (north = -z), origin at the
// centre of the Plaça Vella; the axes are turned 13.7° west of true north like the grid itself. Every street sits where
// it really is: the Rambla d'Ègara runs just west of the origin, the Riera de les Arenes ~1.2 km east of it, the
// Parc de Vallparadís between them. There is no street grid in the sense of the original (numbered streets by z,
// avenues by x): the whole city runs on the street centreline graph (GEO.roadGraph, js/road-network.js) and on the
// real blocks between the streets (GEO.blocks).

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};
const CITY_NAME = GEO.city || 'Terrassa';
const CUT_Z = GEO.frame.cutZ; // northern edge of the detailed area (kept for the modules that bound their work by it)

// ---------------------------------------------------------------------------------------------------------------------
// Land-use & building codes (tools/geo-features.mjs CLS, tools/geo-buildings.mjs BKIND)
// ---------------------------------------------------------------------------------------------------------------------
const LAND_CLASS = { NONE: 0, PARK: 1, SPORTS: 2, WOOD: 3, SCRUB: 4, FARM: 5, INDUSTRIAL: 6, CEMETERY: 7, RAILWAY: 8, PARKING: 9, WATER: 10, CAMPUS: 11, PLAZA: 12, GRASS: 13 };
const LAND_CLASS_NAME = Object.fromEntries(Object.entries(LAND_CLASS).map(([k, v]) => [v, k.toLowerCase()]));
const BUILDING_KIND = { GENERIC: 0, HOUSE: 1, APARTMENTS: 2, INDUSTRIAL: 3, COMMERCIAL: 4, SCHOOL: 5, CHURCH: 6, PUBLIC: 7, LOW: 8 };
// Land classes buildings stand on (the others are open land: parks, woods, fields, water, railways...)
const BUILDABLE_CLASSES = new Set([LAND_CLASS.NONE, LAND_CLASS.INDUSTRIAL, LAND_CLASS.CAMPUS, LAND_CLASS.PARKING, LAND_CLASS.GRASS]);

// ---------------------------------------------------------------------------------------------------------------------
// Street names: OSM names are the real Catalan names in full ("Carrer de Sant Pere", never "C/ Sant Pere"). Unnamed
// stretches (passages, industrial estate roads, slip roads) get a generic label.
// ---------------------------------------------------------------------------------------------------------------------
const UNNAMED = 'Carrer sense nom';
function prettyName(n) {
  if (!n) return UNNAMED;
  const s = n.replace(/\s+/g, ' ').trim();
  // OSM sometimes lower-cases the generic ("carrer del Conflent"): Catalan odonyms capitalise it
  return s.replace(/^(carrer|carretera|avinguda|passeig|rambla|plaça|placeta|passatge|camí|ronda|travessera|via|pont|torrent|riera)\b/, (m) => m[0].toUpperCase() + m.slice(1));
}
// The kind of street from its name, for labels & the maps' hierarchy
const MAJOR_NAME = /^(Avinguda|Rambla|Passeig|Carretera|Ronda|Autopista|Autovia|Via)\b/i;

// ---------------------------------------------------------------------------------------------------------------------
// Land: the detailed area (the urban area of Terrassa), the municipality & its neighbours
// ---------------------------------------------------------------------------------------------------------------------
const LAND_RING = toPts(GEO.land);
const WORLD_BOUNDS = { ...GEO.bounds, sidewalkHeight: 0.15, waterLevel: -1.2 };
const MUNICIPALITY_RINGS = GEO.municipality.map(toPts);
const MUNICIPALITIES = GEO.municipalities.map((m) => ({ name: m.name, population: m.population, rings: m.rings.map(toPts) }));
// West / east edge of the land at a given z (the detail box is a turned rectangle, so its sides slope). Kept under the
// original's name for the modules & tests that clamp to the island's shore: here it is the edge of the detailed area.
const SHORE = (() => {
  const step = 4;
  let z0 = Infinity, z1 = -Infinity;
  for (const p of LAND_RING) { z0 = Math.min(z0, p.z); z1 = Math.max(z1, p.z); }
  z0 = Math.ceil(z0 / step) * step;
  const n = Math.max(2, Math.floor((z1 - z0) / step) + 1);
  const west = new Float32Array(n).fill(NaN);
  const east = new Float32Array(n).fill(NaN);
  const P = LAND_RING;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    const a = P[j], b = P[i];
    if (a.z === b.z) continue;
    const lo = Math.min(a.z, b.z), hi = Math.max(a.z, b.z);
    for (let k = Math.max(0, Math.ceil((lo - z0) / step)); k < n && z0 + k * step < hi; k++) {
      const z = z0 + k * step + 1e-3;
      if (z < lo || z >= hi) continue;
      const x = a.x + ((z - a.z) * (b.x - a.x)) / (b.z - a.z);
      if (!(west[k] <= x)) west[k] = x;
      if (!(east[k] >= x)) east[k] = x;
    }
  }
  for (let k = 1; k < n; k++) if (Number.isNaN(west[k])) { west[k] = west[k - 1]; east[k] = east[k - 1]; }
  for (let k = n - 2; k >= 0; k--) if (Number.isNaN(west[k])) { west[k] = west[k + 1]; east[k] = east[k + 1]; }
  return { z0, step, n, west, east };
})();
/** West / east x of the detailed land at a given z, clamped at its ends (the original's island shore lookup) */
function getIslandBoundsAtZ(z) {
  const f = (z - SHORE.z0) / SHORE.step;
  const k = Math.max(0, Math.min(SHORE.n - 2, Math.floor(f)));
  const t = Math.max(0, Math.min(1, f - k));
  return {
    westX: SHORE.west[k] + (SHORE.west[k + 1] - SHORE.west[k]) * t,
    eastX: SHORE.east[k] + (SHORE.east[k + 1] - SHORE.east[k]) * t
  };
}
function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
const onLand = (x, z) => pointInPoly(LAND_RING, x, z);

// ---------------------------------------------------------------------------------------------------------------------
// Roads: every street polyline (the real centreline, one per OSM way) for the maps, labels & nearest-road lookups
//   [name, curb-to-curb width, dir, lanes, class (0 street, 1 motorway, 2 primary / secondary, 3 pedestrian, 4 service)]
// ---------------------------------------------------------------------------------------------------------------------
const ROADS = GEO.roads.map(([name, w, dir, lanes, cls, flat]) => ({
  name: prettyName(name), raw: name, w, dir, lanes, cls, highway: cls === 1, major: cls === 1 || cls === 2 || MAJOR_NAME.test(name), pedestrian: cls === 3, pts: toPts(flat)
}));
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i], b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist, ux, uz }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const px = s.ax + t * dx, pz = s.az + t * dz;
      const d = Math.hypot(px - x, pz - z);
      if (d > radius) continue;
      const key = s.r.name === UNNAMED ? `${UNNAMED}#${ROADS.indexOf(s.r)}` : s.r.name;
      const prev = best.get(key);
      if (!prev || d < prev.dist) {
        const L = Math.sqrt(L2);
        best.set(key, { road: s.r, dist: d, ux: dx / L, uz: dz / L, px, pz, horizontal: Math.abs(dx) > Math.abs(dz) });
      }
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}
// Street database for the maps' search & labels: one entry per distinct name, with its extent
const STREET_INDEX = (() => {
  const byName = new Map();
  for (const r of ROADS) {
    if (r.name === UNNAMED) continue;
    let e = byName.get(r.name);
    if (!e) byName.set(r.name, (e = { name: r.name, short: r.name, roads: [], major: r.major, minX: Infinity, maxX: -Infinity, minZ: Infinity, maxZ: -Infinity, length: 0 }));
    e.roads.push(r);
    e.major = e.major || r.major;
    for (let i = 0; i < r.pts.length; i++) {
      const p = r.pts[i];
      e.minX = Math.min(e.minX, p.x); e.maxX = Math.max(e.maxX, p.x); e.minZ = Math.min(e.minZ, p.z); e.maxZ = Math.max(e.maxZ, p.z);
      if (i) e.length += Math.hypot(p.x - r.pts[i - 1].x, p.z - r.pts[i - 1].z);
    }
  }
  const list = [...byName.values()];
  for (const e of list) { e.x = (e.minX + e.maxX) / 2; e.z = (e.minZ + e.maxZ) / 2; }
  return list.sort((a, b) => b.length - a.length);
})();

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every real curb island with its lot rectangles inside the property line, its land use & its neighbourhood
//   poly: curb outline [{x, z}], rects: [[x0, x1, z0, z1], ...] building lots (axis-aligned), frames: lots laid out
//   along the streets the block fronts, [[θ, px, pz, rects], ...] (world = p + R_y(θ)·(local − p)), cls: dominant land
//   use (LAND_CLASS), park: share of parkland / squares, parkName, district, buildings: real footprints as boxes
//   [θ, cx, cz, levels, height, kind, roof, rects (local, about (cx, cz)), area], cover: footprint share of the lots
// ---------------------------------------------------------------------------------------------------------------------
const DISTRICTS = GEO.districts.map((d, i) => ({ id: i, name: d.name, x: d.x, z: d.z }));
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames, cls, clsShare, district, buildings, cover, shares], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  const open = !BUILDABLE_CLASSES.has(cls) && clsShare >= 0.5;
  return {
    id, poly, rects, frames: frames || null, park, parkName, rect: !!isRect, area,
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    cls, clsShare, shares: shares || [], open,
    district: DISTRICTS[district] ? DISTRICTS[district].name : '',
    districtId: district,
    buildings: buildings || [],
    cover: cover || 0,
    // thin slabs between two roadways (planted medians of the avenues & the Rambla)
    median: Math.min(maxX - minX, maxZ - minZ) < 9 && area < 1500
  };
});
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
/** The block (curb island) under (x, z), or null on the roadway */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.rect || pointInPoly(b.poly, x, z)) return b;
  }
  return null;
}
/** Blocks whose bounds overlap a rectangle */
function blocksInRect(minX, maxX, minZ, maxZ) {
  const out = new Set();
  for (let ix = Math.floor(minX / BLOCK_CELL); ix <= Math.floor(maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(minZ / BLOCK_CELL); iz <= Math.floor(maxZ / BLOCK_CELL); iz++) {
      const list = BLOCK_GRID.get(ix * 100000 + iz);
      if (list) for (const b of list) if (b.maxX > minX && b.minX < maxX && b.maxZ > minZ && b.minZ < maxZ) out.add(b);
    }
  }
  return [...out];
}

// ---------------------------------------------------------------------------------------------------------------------
// Neighbourhoods (barris): the nearest place node (HOW_TO_IMPROVE.md §2.6) & the building typology of each barri, for
// the procedural buildings where OSM has no footprints (buildings.js) and the maps' labels.
//   kind: oldtown (the medieval core: 3-5 storey houses on narrow irregular lots, shops everywhere), eixample (the
//   19th-20th c. grid: "cases de cos" 5-7 m wide row houses of 2-3 storeys and 4-6 storey corner & avenue blocks with
//   flat roofs — terrats), blocs (1960s-70s working-class estates: 5-12 storey slab blocks on open ground),
//   suburban (detached & semi-detached 1-2 storey houses), industrial (naves: 1-2 storey sheds, the old vapors),
//   mixed (industrial estate with housing)
// ---------------------------------------------------------------------------------------------------------------------
const DISTRICT_PROFILES = {
  oldtown: { kind: 'oldtown', floors: [3, 5], tall: 0.08, shops: 0.9, rowWidth: [5, 9], flatRoof: 0.75 },
  eixample: { kind: 'eixample', floors: [2, 5], tall: 0.12, shops: 0.45, rowWidth: [5, 8], flatRoof: 0.85 },
  eixampleDense: { kind: 'eixample', floors: [3, 6], tall: 0.2, shops: 0.6, rowWidth: [5.5, 9], flatRoof: 0.9 },
  blocs: { kind: 'blocs', floors: [5, 11], tall: 0.3, shops: 0.35, rowWidth: [12, 30], flatRoof: 1.0 },
  suburban: { kind: 'suburban', floors: [1, 2], tall: 0, shops: 0.03, rowWidth: [9, 16], flatRoof: 0.3 },
  industrial: { kind: 'industrial', floors: [1, 2], tall: 0, shops: 0.05, rowWidth: [18, 50], flatRoof: 0.6 },
  mixed: { kind: 'mixed', floors: [2, 6], tall: 0.1, shops: 0.3, rowWidth: [8, 24], flatRoof: 0.9 }
};
const DISTRICT_KIND = {
  'Centre': 'oldtown',
  'Ca n\'Aurell': 'eixampleDense', 'Sant Pere': 'eixampleDense', 'Vallparadís': 'eixampleDense', 'Plaça Catalunya-Escola Industrial': 'eixampleDense',
  'Barri Universitari-Cementiri Vell': 'eixample', 'Antic Poble de Sant Pere': 'eixample', 'Segle XX': 'eixample', 'la Cogullada': 'eixample',
  'la Maurina': 'eixample', 'Ca n\'Anglada': 'eixample', 'Torrent d\'en Pere Parres': 'eixample', 'Can Palet': 'eixample', 'Montserrat': 'eixample',
  'Guadalhorce': 'eixample', 'Can Boada Casc Antic': 'eixample', 'Vilardell': 'eixample',
  'Sant Llorenç': 'blocs', 'Ègara': 'blocs', 'Sant Pere Nord': 'blocs', 'Can Jofresa': 'blocs', 'Xúquer': 'blocs', 'Can Palet II': 'blocs',
  'Torre-sana': 'blocs', 'Can Tusell': 'blocs', 'Roc Blanc': 'blocs', 'Can Boada del Pi': 'blocs', 'Poble Nou-Zona Esportiva': 'blocs', 'Can Roca': 'blocs',
  'Pla del Bon Aire': 'suburban', 'Pla del Bon Aire-el Garrot': 'suburban', 'les Martines': 'suburban', 'Can Palet de Vista Alegre': 'suburban',
  'Vista Alegre': 'suburban', 'Can Gonteres': 'suburban', 'Sant Miquel de Gonteres': 'suburban', 'Can Tries': 'suburban', 'Can Vinyers': 'suburban',
  'la Plana': 'suburban', 'la Muntanyeta': 'suburban', 'Mas Sot': 'suburban', 'Can Duran': 'suburban', 'Can Candi': 'suburban', 'Can Pepet': 'suburban',
  'Sant Llorenç dels Pins': 'suburban', 'Can Solà del Racó': 'suburban', 'Verge de Montserrat': 'suburban', 'la Font de l\'Espardenyera': 'suburban',
  'Polígon industrial Can Tries': 'industrial', 'les Arenes, la Grípia i Can Montllor': 'mixed'
};
/** Building typology of a block: its land use first (industrial estates, campuses), then its barri */
function blockProfile(b) {
  if (b.cls === LAND_CLASS.INDUSTRIAL && b.clsShare > 0.4) return DISTRICT_PROFILES.industrial;
  if (b.cls === LAND_CLASS.CAMPUS && b.clsShare > 0.4) return { ...DISTRICT_PROFILES.mixed, kind: 'campus', floors: [2, 4], shops: 0 };
  return DISTRICT_PROFILES[DISTRICT_KIND[b.district] || 'eixample'];
}
/** The barri at (x, z): the block's, or the nearest place node on the roadway */
function districtAt(x, z) {
  const b = blockAt(x, z);
  if (b && b.district) return b.district;
  let best = '', bd = Infinity;
  for (const d of DISTRICTS) { const dd = Math.hypot(d.x - x, d.z - z); if (dd < bd) { bd = dd; best = d.name; } }
  return best;
}

// ---------------------------------------------------------------------------------------------------------------------
// Parks, squares, land use, streams, railways, trees (real outlines from OpenStreetMap)
// ---------------------------------------------------------------------------------------------------------------------
const PARKS = GEO.parks.map((p) => ({ name: p.name, cls: p.cls, area: p.area, rings: p.rings.map(toPts) }));
const LANDUSE = GEO.landuse.map((l) => ({ cls: l.cls, name: l.name, area: l.area, rings: l.rings.map(toPts) }));
const WATERWAYS = GEO.water.map((w) => ({ name: w.name, w: w.w, pts: toPts(w.pts) }));
const RAIL_LINES = GEO.rail.map((r) => ({ name: r.name, bridge: r.bridge, pts: toPts(r.pts) }));
const STREET_TREES = toPts(GEO.trees);
const SQUARES = GEO.squares.slice();
// Named shops & businesses (OpenStreetMap POIs): the real signs at their real doors
//   kind: 0 shop, 1 bar / restaurant / café, 2 bank, 3 pharmacy / health, 4 office, 5 hotel, 6 fuel, 7 other
const SHOPS = (GEO.shops || []).map(([name, kind, type, x, z]) => ({ name, kind, type, x, z }));
const parkByName = (name) => PARKS.find((p) => p.name === name) || null;
/** The named park / square whose outline contains (x, z), or null */
function parkAt(x, z) {
  for (const p of PARKS) if (pointInPoly(p.rings[0], x, z)) return p;
  return null;
}

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks (real footprints from OpenStreetMap: centre, bounds, outline, height when known; HOW_TO_IMPROVE.md §2.7)
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = {};
for (const [name, l] of Object.entries(GEO.landmarks)) LANDMARK_SITES[name] = { ...l, ring: l.ring ? toPts(l.ring) : null };
const site = (name) => LANDMARK_SITES[name] || null;
// Terrassa's best-known places: [id, display name, short name, OSM name(s) to find the site, barri]
const CITY_LANDMARKS = [
  ['catedral', 'Catedral Basílica del Sant Esperit', 'Catedral', ['Catedral del Sant Esperit'], 'Centre'],
  ['ajuntament', 'Ajuntament de Terrassa · Raval de Montserrat', 'Ajuntament', ['Ajuntament de Terrassa'], 'Centre'],
  ['torrepalau', 'Torre del Palau', 'Torre del Palau', ['Torre del Palau'], 'Centre'],
  ['mercat', 'Mercat de la Independència', 'Mercat', ['Mercat de la Independència'], 'Centre'],
  ['masiafreixa', 'Masia Freixa · Parc de Sant Jordi', 'Masia Freixa', ['Masia Freixa'], 'Ca n\'Aurell'],
  ['mnactec', 'Museu de la Ciència i de la Tècnica (Vapor Aymerich, Amat i Jover)', 'mNACTEC', ['Vapor Aymerich, Amat i Jover', 'Museu Nacional de la Ciència i de la Tècnica de Catalunya'], 'Centre'],
  ['seu', 'Seu d\'Ègara · Esglésies de Sant Pere', 'Seu d\'Ègara', ['Santa Maria', 'Sant Pere', 'La Seu d\'Ègara'], 'Antic Poble de Sant Pere'],
  ['cartoixa', 'Castell Cartoixa de Vallparadís', 'Cartoixa', ['Castell Cartoixa de Vallparadís'], 'Vallparadís'],
  ['teatre', 'Teatre Principal', 'Teatre Principal', ['Teatre Principal'], 'Centre'],
  ['estacionord', 'Estació del Nord (Rodalies)', 'Estació del Nord', ['Estació de Terrassa Estació del Nord (ADIF)', 'Terrassa Estació del Nord'], 'Centre'],
  ['mutua', 'Hospital Universitari Mútua Terrassa', 'Mútua', ['Hospital Mútua de Terrassa'], 'Centre'],
  ['estadi', 'Estadi Olímpic de Terrassa', 'Estadi Olímpic', ['Estadi Municipal Olímpic'], 'Poble Nou-Zona Esportiva'],
  ['vallparadis', 'Parc de Vallparadís', 'Vallparadís', ['Parc de Vallparadís'], 'Vallparadís'],
  ['santjordi', 'Parc de Sant Jordi', 'Parc de Sant Jordi', ['Parc de Sant Jordi'], 'Ca n\'Aurell'],
  ['bovila', 'Xemeneia de la Bòvila Almirall', 'Bòvila Almirall', ['Xemeneia de la Bòvila Almirall'], 'Ca n\'Aurell'],
  ['hospital', 'Hospital de Terrassa', 'Hospital de Terrassa', ['Hospital de Terrassa'], 'les Arenes, la Grípia i Can Montllor']
].map(([id, name, short, osmNames, district]) => {
  let s = null;
  for (const n of osmNames) if ((s = site(n))) break;
  if (!s && id === 'vallparadis') { const p = parkByName('Parc de Vallparadís'); if (p) { const c = p.rings[0].reduce((t, q) => ({ x: t.x + q.x / p.rings[0].length, z: t.z + q.z / p.rings[0].length }), { x: 0, z: 0 }); s = { x: c.x, z: c.z }; } }
  if (!s) return null;
  return { id, name, short, x: s.x, z: s.z, district, site: s, osm: osmNames[0] };
}).filter(Boolean);
// Landmark sites landmarks.js models itself (buildings.js leaves their footprints empty). OSM names, see LANDMARK_SITES.
const MODELLED_LANDMARKS = [
  'Catedral del Sant Esperit', 'Masia Freixa', 'Torre del Palau', 'Castell Cartoixa de Vallparadís', 'Mercat de la Independència',
  'Ajuntament de Terrassa', 'Antic Ajuntament de Terrassa', 'Vapor Aymerich, Amat i Jover', 'Museu Nacional de la Ciència i de la Tècnica de Catalunya', 'Teatre Principal', 'Santa Maria', 'Sant Pere', 'Sant Miquel',
  'Hospital Mútua de Terrassa', 'Estadi Municipal Olímpic', 'Estació de Terrassa Estació del Nord (ADIF)', 'Estació de Terrassa Est',
  'Casa Museu Alegre de Sagrera', 'Museu Tèxtil', 'Gran Casino', 'Casa Baumann', 'Hospital de Terrassa', 'Institut Industrial',
  'Xemeneia de la Bòvila Almirall', 'Xemeneia de la Bòvila Almirall (2)', 'Xemeneia Terrassa Industrial', 'Xemeneia Tintoreria Lanera',
  'Xemeneia Manufactura auxiliar', 'Xemeneia TIP,SA', 'Xemeneia de Cal Guardiola', 'Xemeneia Vapor Montset', 'Xemeneia del Vapor Amat', 'Carrilló del mNACTEC'
].filter((n) => LANDMARK_SITES[n]);
// The Plaça Vella itself (the origin), as a place
CITY_LANDMARKS.unshift({ id: 'placavella', name: 'Plaça Vella', short: 'Plaça Vella', x: 0, z: 0, district: 'Centre', site: null, osm: 'Plaça Vella' });

// ---------------------------------------------------------------------------------------------------------------------
// Teleports: street-level arrivals near the landmarks, on the nearest drivable street (shared by every travel mode).
// Heading 0 faces south (+z), PI north. Each is placed on the carriageway, 1.8 m right of the centreline, facing the
// landmark along the street.
// ---------------------------------------------------------------------------------------------------------------------
function streetSpotNear(x, z, radius = 120, prefer = null) {
  const near = nearestRoads(x, z, radius).filter((r) => r.road.cls !== 3 && r.road.cls !== 4 && r.road.w >= 5);
  if (!near.length) return null;
  let pick = prefer ? near.find((r) => r.road.name === prefer) : null;
  if (!pick) pick = near.find((r) => r.dist > 12) || near[0]; // not right on top of the landmark's own kerb
  // along the street, facing the landmark
  const towards = (x - pick.px) * pick.ux + (z - pick.pz) * pick.uz >= 0 ? 1 : -1;
  const ux = pick.ux * towards, uz = pick.uz * towards;
  const rx = -uz, rz = ux; // right of the direction of travel
  const px = pick.px + rx * 1.8, pz = pick.pz + rz * 1.8;
  return { x: Math.round(px * 10) / 10, z: Math.round(pz * 10) / 10, heading: Math.atan2(ux, uz), street: pick.road.name };
}
const TELEPORT_LOCATIONS = {};
for (const [key, lmId, prefer] of [
  ['placavella', 'placavella', 'Carrer de la Font Vella'], ['catedral', 'catedral', 'Carrer de la Font Vella'], ['masiafreixa', 'masiafreixa', 'Carrer de Volta'],
  ['rambla', 'mnactec', 'Rambla d\'Ègara'], ['vallparadis', 'cartoixa', 'Carrer de Salmerón'], ['mercat', 'mercat', 'Raval de Montserrat'],
  ['estacionord', 'estacionord', 'Carrer de l\'Estació'], ['estadi', 'estadi', 'Avinguda de l\'Abat Marcet'], ['seu', 'seu', 'Carrer de la Rectoria'], ['mutua', 'mutua', 'Plaça del Doctor Robert']
]) {
  const lm = CITY_LANDMARKS.find((l) => l.id === lmId);
  if (!lm) continue;
  const spot = streetSpotNear(lm.x, lm.z, 160, prefer);
  if (spot) TELEPORT_LOCATIONS[key] = spot;
}
// The spawn: on the Rambla d'Ègara by the Plaça Vella (every mode starts here; controllers.js offsets each a little)
const SPAWN = TELEPORT_LOCATIONS.placavella || streetSpotNear(0, 0, 200) || { x: 0, z: 40, heading: Math.PI };

// ---------------------------------------------------------------------------------------------------------------------
// Location label at any world (x, z): the landmark, park or square you are at, with the nearest streets
//   "Catedral Basílica del Sant Esperit · Carrer de la Font Vella" / "Carrer de Sant Pere · Carrer de la Rutlla" /
//   "Parc de Vallparadís · near Carrer de Salmerón"
// ---------------------------------------------------------------------------------------------------------------------
function twoStreets(near) {
  const first = near.find((r) => r.road.name !== UNNAMED) || near[0];
  if (!first) return [];
  // the second street crosses the first (at least 25°) and has another name
  const second = near.find((r) => r !== first && r.road.name !== first.road.name && r.road.name !== UNNAMED && Math.abs(r.ux * first.uz - r.uz * first.ux) > 0.42);
  return second ? [first, second] : [first];
}
function getLocationLabel(x, z) {
  for (const lm of CITY_LANDMARKS) {
    const s = lm.site;
    if (s && s.kind === 'park') continue; // parks by their outline, below
    const reach = s && s.w ? Math.min(140, Math.max(40, Math.hypot(s.w, s.d) * 0.5 + 25)) : 60;
    if (Math.hypot(x - lm.x, z - lm.z) < reach) {
      const st = twoStreets(nearestRoads(x, z, 120));
      return `${lm.name}${st.length ? ` · ${st.map((r) => r.road.name).join(' & ')}` : ''}`;
    }
  }
  const park = parkAt(x, z);
  if (park) {
    const st = twoStreets(nearestRoads(x, z, 160));
    return `${park.name}${st.length ? ` · near ${st[0].road.name}` : ''}`;
  }
  const near = nearestRoads(x, z, 160);
  const st = twoStreets(near);
  if (st.length === 2) return `${st[0].road.name} & ${st[1].road.name}`;
  if (st.length === 1) return st[0].road.name;
  if (!onLand(x, z)) return 'Vallès Occidental';
  return districtAt(x, z) || CITY_NAME;
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds: the
// main road (group 0 at each junction) is green until mainAmber, amber until mainRed; the cross streets are green from
// mainRed until crossAmber, amber until the end of the cycle. Pedestrians cross with the traffic that runs parallel to
// them, stepping off only on the WALK, the first `walk` seconds of its green.
// Feature switches (NEXT_STEPS.md: every improvement lands behind one, so it can be turned off in seconds)
const FEATURES = {
  terrain: true, // the real relief (js/terrassa-terrain.bin via js/terrain.js); off, or without the file, the city is flat
  terrainFile: './js/terrassa-terrain.bin', // its cell size (10 m) is the lattice the asphalt deck is drawn on
  terrainTile: 500, // m: deck tiles, so frustum culling drops the ground behind the camera
  // Driving (NEXT_STEPS.md §2.1): the four-wheel driving model of js/vehicle-physics.js for the player's car (engine &
  // gearbox, one spring per wheel, saturating tyres, gravity on the slopes) instead of the arcade "speed along the heading"
  carPhysics: true,
  // The player collides with the street furniture & the trees (lamp posts, signal poles, bollards, bins, benches, trunks),
  // not only with the buildings
  propCollisions: true,
  // A catalogue of selectable cars (taxi, compact, SUV, the two police forces, a hot hatch) with their own dynamics
  vehicleGarage: true,
  // Get out of the car or off the bike and walk, get back in, take a parked bicycle from a rack (F)
  enterExit: true,
  // Police with states: patrol (no siren, no lights, obeys the signals) and emergency runs; Mossos d'Esquadra beside the
  // Policia Municipal. Off: every police car runs with its siren on, as in the original
  emergencyStates: true
};

const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for the main road (isAvenue) or the cross streets at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside the main road (or the cross street) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

